pub mod nouns;

// NOTE: `main` is intentionally NOT `#[tokio::main]`. The `clap-noun-verb`
// dispatch is synchronous and the `serve` verb drives the async LSP server on
// its own runtime; if `main` established an ambient runtime, that verb's
// `block_on` would panic with "Cannot start a runtime from within a runtime".
fn main() -> clap_noun_verb::Result<()> {
    // An LSP client (Claude Code, editors) spawns the binary with no arguments
    // and speaks JSON-RPC over stdio. Default that bare invocation to the
    // server so it works regardless of how it's launched; explicit verbs
    // (`serve --stdio`, `scan`, `--help`, …) still route through the framework.
    if std::env::args().nth(1).is_none() {
        let rt = tokio::runtime::Runtime::new().expect("failed to build tokio runtime");
        rt.block_on(nouns::config::start_stdio_server());
        return Ok(());
    }
    clap_noun_verb::run()
}
